type Shop = { id: string; code: string; name: string; status: string; manager: string | null; opening: { status: string; step: number } | null; updatedAt?: string; currency?: string; timezone?: string; openingDrafts?: Array<{ status: string; step: number; version: number }> };
type Product = { id: string; name: string; sku: string | null; family: string | null; status: string; imageUrl: string | null; tracksLots: boolean; tracksExpiry: boolean; variants: Variant[] };
type Variant = { id: string; name: string; costs?: { lastUnitCostMinor: string | null; weightedAverageUnitCostMinor: string | null; layers: Array<{ id: string; originType: string; remainingQuantity: string; unitCostMinor: string; receivedAt: string; location: string }> }; units: Array<{ id: string; name: string; symbol: string; factor: string; prices: Array<{ amountMinor: string; validFrom: string; validUntil: string | null }> }> };
type Source = { id: string; shopId: string | null; name: string; type: string; status: string; accounts: Array<{ id: string; currency: string; balanceMinor: string }> };
type Location = { id: string; name: string; type: string; status: string; shopId: string | null; shop?: { id: string; code: string; name: string; status: string; manager: string | null } | null; productCount?: number; variantCount?: number; stockLineCount?: number; lastUpdatedAt?: string | null };
type Stock = { id: string; productId?: string; variantId?: string; locationId?: string; product: string; variant: string; quantity: string; location: string; shopId: string | null; updatedAt: string };
type StockMovement = { id: string; type: string; postedAt: string; entries: Array<{ product: string; variant: string; location: string; quantity: string; lot: string | null; expiresAt: string | null }> };
type OpeningStockLine = { variantId: string; locationId: string; quantity: string; unitCostMinor: string };
type OpeningFundLine = { accountId: string; amountMinor: string };

function useLoad<T>(path: string) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const reload = useCallback(() => api<T>(path).then(setData).catch((caught: RequestError) => setError(caught.message)), [path]);
  useEffect(() => { void reload(); }, [reload]);
  return { data, error, reload };
}

function Feedback({ error, success }: { error: string | null; success: string | null }) {
  const message = error ?? success;
  const [visible, setVisible] = useState(false);
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  useEffect(() => {
    if (!message) { setVisible(false); return; }
    setVisible(true);
    const timeout = window.setTimeout(() => setVisible(false), error ? 7000 : 4500);
    return () => window.clearTimeout(timeout);
  }, [message, error]);
  if (!mounted) return null;
  return createPortal(<div className="pointer-events-none fixed inset-x-4 top-4 z-30 flex justify-center sm:justify-end"><AnimatePresence>{visible && message ? <motion.div role={error ? "alert" : "status"} initial={{ opacity: 0, y: -12, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: -8, scale: 0.98 }} transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }} className={`pointer-events-auto flex w-full max-w-md items-start gap-3 rounded-lg bg-[var(--surface)] p-4 shadow-[var(--shadow-float)] ring-1 ${error ? "ring-[color-mix(in_srgb,var(--destructive)_24%,transparent)]" : "ring-[color-mix(in_srgb,var(--success)_24%,transparent)]"}`}>{error ? <AlertCircle className="mt-0.5 size-5 shrink-0 text-[var(--destructive)]" /> : <CheckCircle2 className="mt-0.5 size-5 shrink-0 text-[var(--success)]" />}<div className="min-w-0 flex-1"><p className="text-sm font-semibold">{error ? "Action impossible" : "Modification enregistrée"}</p><p className="mt-0.5 text-sm leading-5 text-[var(--muted)]">{message}</p></div><button type="button" onClick={() => setVisible(false)} className="grid size-7 shrink-0 place-items-center rounded-md text-[var(--muted)] transition-colors hover:bg-[var(--surface-subtle)] hover:text-[var(--foreground)]" aria-label="Fermer la notification"><X className="size-4" /></button></motion.div> : null}</AnimatePresence></div>, document.body);
}

function Field({ id, label, ...props }: React.ComponentProps<typeof Input> & { id: string; label: string }) {
  return <div className="space-y-1.5"><Label htmlFor={id}>{label}</Label><Input id={id} {...props} /></div>;
}

const panel = "rounded-lg bg-[var(--surface)] p-5 shadow-[var(--shadow-card)]";

